import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;

const now = () => new Date().toISOString();

function beat(): void {
  try {
    db.prepare('INSERT INTO heartbeat (name, beat_at) VALUES (?, ?) ON CONFLICT(name) DO UPDATE SET beat_at = excluded.beat_at')
      .run('worker', Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}

// Any job left "running" belongs to a worker that died (only one worker runs at a time): requeue it.
db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'").run(now());
beat();
const heartbeatTimer = setInterval(beat, 1000);

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const selectNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1",
);
const claim = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = ?, progress = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
);
const setProgress = db.prepare("UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const complete = db.prepare(
  "UPDATE jobs SET status = 'completed', progress = ?, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
);
const retry = db.prepare(
  "UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const fail = db.prepare(
  "UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const requeue = db.prepare(
  "UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'",
);

async function processJob(job: JobRow): Promise<void> {
  // An attempt interrupted by a crash/shutdown on the final attempt is re-run as that same attempt.
  const attempt = Math.min(job.attempts + 1, MAX_ATTEMPTS);
  if (claim.run(attempt, now(), job.id).changes !== 1) return;

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (step === 1 && attempt <= job.fail_attempts) {
      if (attempt >= MAX_ATTEMPTS) fail.run('transient failure', now(), job.id);
      else retry.run(Date.now() + RETRY_DELAY_MS, now(), job.id);
      return;
    }
    if (step === job.steps) {
      complete.run(step, job.input.toUpperCase(), now(), job.id);
      return;
    }
    setProgress.run(step, now(), job.id);
    if (stopping) {
