const getByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const listAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idempotency_key, payload, run_after, created_at, updated_at)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)
`);
const getHeartbeat = db.prepare('SELECT beat_at FROM heartbeat WHERE name = ?');

const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED = new Set(['input', 'steps', 'failAttempts']);

function checkInt(value: unknown, field: string, min: number, max: number, errors: FieldError[]): void {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    errors.push({ field, message: `${field} must be an integer` });
  } else if (!Number.isInteger(value)) {
    errors.push({ field, message: `${field} must be an integer` });
  } else if (value < min || value > max) {
    errors.push({ field, message: `${field} must be between ${min} and ${max}` });
  }
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const errors: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  const key = Array.isArray(keyHeader) ? keyHeader.join(',') : keyHeader;
  if (key !== undefined && !KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' });
  }

