    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === null) {
    errors.push({ field: 'body', message: 'Request body is too large' });
  } else {
    try {
      body = JSON.parse(raw);
      if (typeof body !== 'object' || body === null || Array.isArray(body)) {
        errors.push({ field: 'body', message: 'Request body must be a JSON object' });
      } else {
        bodyOk = true;
      }
    } catch {
      errors.push({ field: 'body', message: 'Request body must be valid JSON' });
    }
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (bodyOk) {
    const obj = body as Record<string, unknown>;
    for (const k of Object.keys(obj)) {
      if (!ALLOWED.has(k)) errors.push({ field: k, message: `Unknown field: ${k}` });
    }
    if (!('input' in obj) || obj.input === undefined) {
      errors.push({ field: 'input', message: 'input is required' });
    } else if (typeof obj.input !== 'string') {
      errors.push({ field: 'input', message: 'input must be a string' });
    } else if (obj.input.length < 1 || obj.input.length > 1000) {
      errors.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
    } else if (obj.input.trim() === '') {
      errors.push({ field: 'input', message: 'input must not be only whitespace' });
    } else {
      input = obj.input;
    }
    if ('steps' in obj) {
      checkInt(obj.steps, 'steps', 1, 20, errors);
      if (typeof obj.steps === 'number') steps = obj.steps;
    }
    if ('failAttempts' in obj) {
      checkInt(obj.failAttempts, 'failAttempts', 0, 5, errors);
      if (typeof obj.failAttempts === 'number') failAttempts = obj.failAttempts;
    }
  }

