  if (key !== undefined) {
    const existing = getByKey.get(key) as JobRow | undefined;
    if (existing) {
      if (existing.payload === payload) return send(res, 200, toJob(existing));
      return sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
    }
  }

  const id = randomUUID();
  const ts = new Date().toISOString();
  try {
    insertJob.run(id, input, steps, failAttempts, key ?? null, payload, ts, ts);
  } catch (err) {
    // Unique constraint race on the idempotency key: resolve against the stored job.
    if (key !== undefined) {
      const existing = getByKey.get(key) as JobRow | undefined;
      if (existing) {
        if (existing.payload === payload) return send(res, 200, toJob(existing));
        return sendError(res, 409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
