  sendError(res, 405, 'method_not_allowed', 'Method not allowed.', undefined, { allow });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';

  if (pathname === '/health') {
    if (!isGet) return methodNotAllowed(res, 'GET');
    const row = getHeartbeat.get('worker') as { beat_at: number } | undefined;
    const up = row !== undefined && Date.now() - row.beat_at <= HEARTBEAT_STALE_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/' || pathname === '/index.html') {
    if (!isGet) return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return createJob(req, res);
    if (!isGet) return methodNotAllowed(res, 'GET, POST');
    const rows = listAll.all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (!isGet) return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      id = m[1]!;
    }
    const row = getById.get(id) as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err) => {
    console.error(err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (shuttingDown) return;
    shuttingDown = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeAllConnections();
    setTimeout(() => process.exit(0), 2000).unref();
  });
}

